function lowerHeaders(headers) {
  const result = {};
  Object.keys(headers || {}).forEach((k) => { result[String(k).toLowerCase()] = headers[k]; });
  return result;
}

const root = $input.first().json;
const headers = lowerHeaders(root.headers);
const secret = $env.CHATWOOT_WEBHOOK_SECRET;
if (secret) {
  const got = headers['x-webhook-secret'] || headers['x-chatwoot-secret'];
  if (String(got || '') !== String(secret)) return [{ json: { skip: true, reason: 'bad_secret' } }];
}

const payload = root.body && typeof root.body === 'object' ? root.body : root;
if (payload.event !== 'message_created') return [{ json: { skip: true, reason: 'unsupported_event' } }];

const message = payload.message && typeof payload.message === 'object' ? payload.message : payload;
const conversation = payload.conversation || {};
const lastConversationMessage = Array.isArray(conversation.messages) ? (conversation.messages.find((item) => String(item.id) === String(message.id || payload.id)) || conversation.messages[0] || {}) : {};
const sender = message.sender || payload.sender || payload.contact || {};
const senderType = String(sender.type || message.sender_type || payload.sender_type || message.senderType || payload.senderType || lastConversationMessage.sender_type || lastConversationMessage.sender?.type || conversation.meta?.sender?.type || (payload.contact ? 'contact' : '')).toLowerCase();
const isContact = senderType === 'contact';
const mt = message.message_type ?? payload.message_type;
const isIncoming = mt === 0 || mt === '0' || String(mt).toLowerCase() === 'incoming';
const isPrivate = message.private === true || payload.private === true;
if (isPrivate || !isContact || !isIncoming) return [{ json: { skip: true, reason: 'not_customer_incoming' } }];

const account = payload.account || {};
const inbox = payload.inbox || {};
const contact = payload.contact || ((senderType === 'contact' && sender.type) ? sender : undefined) || conversation.meta?.sender || lastConversationMessage.sender || {};
const accountId = account.id;
const conversationId = conversation.id || conversation.display_id || payload.conversation_id;
const messageId = message.id || payload.id;
const userText = String(message.content || payload.content || '').trim();
if (!accountId || !conversationId || !messageId) return [{ json: { skip: true, reason: 'missing_ids' } }];

return [{ json: { skip: false, accountId, conversationId, messageId, userText, inboxId: conversation.inbox_id || inbox.id, contactId: contact.id || conversation.contact_inbox?.contact_id || lastConversationMessage.sender_id, senderType, rawPayload: payload } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.seenMessages) staticData.seenMessages = {};
if (!staticData.convDebounce) staticData.convDebounce = {};

const item = $input.first().json;
const messageId = String(item.messageId);
const convId = String(item.conversationId);
const now = Date.now();
const windowMs = Number($env.IDEMPOTENCY_WINDOW_MS || 120000);
const debounceMs = Number($env.CONVERSATION_DEBOUNCE_MS || 2000);
for (const k of Object.keys(staticData.seenMessages)) {
  if (now - staticData.seenMessages[k] > windowMs) delete staticData.seenMessages[k];
}
if (staticData.seenMessages[messageId]) return [{ json: { ...item, skip: true, reason: 'duplicate_message' } }];
const last = staticData.convDebounce[convId] || 0;
if (now - last < debounceMs) return [{ json: { ...item, skip: true, reason: 'conversation_debounce' } }];
staticData.seenMessages[messageId] = now;
staticData.convDebounce[convId] = now;
return [{ json: { ...item, skip: false } }];

const base = $('Idempotency & Debounce').first().json;
const conversation = $('Chatwoot Get Conversation').first().json || {};
const messagesResponse = $('Chatwoot List Messages').first().json || {};
const contact = $input.first().json || {};
const contactFetchFailed = Boolean(base.contactId && contact.error);
const contextFailed = Boolean(conversation.error || messagesResponse.error || contactFetchFailed);

const source = messagesResponse.payload ?? messagesResponse.data ?? messagesResponse;
let list = [];
if (Array.isArray(source)) list = source;
else if (Array.isArray(source?.payload)) list = source.payload;
else if (Array.isArray(source?.data?.payload)) list = source.data.payload;

const recent = list.filter((m) => m && String(m.content || '').trim() && m.private !== true && m.private !== 'true').slice(-12);
const transcript = recent.map((m) => {
  const mt = m.message_type;
  const inbound = mt === 0 || mt === '0' || String(mt).toLowerCase() === 'incoming';
  return `${inbound ? 'customer' : 'agent'}: ${String(m.content || '').trim()}`;
}).join('\n');

const labels = conversation.labels || conversation.payload?.labels || [];
const customAttributes = conversation.custom_attributes || conversation.payload?.custom_attributes || {};
const additionalAttributes = conversation.additional_attributes || conversation.payload?.additional_attributes || {};
return [{ json: { ...base, conversation, contact: base.contactId ? contact : {}, transcript, labels, customAttributes, additionalAttributes, contextFailed } }];

const text = String($json.userText || '').toLowerCase();
const flags = [];
const labels = [];
if (/\b(human|agent|person|representative)\b/.test(text)) flags.push('human_requested');
if (/\b(password|token|secret|api key|credential|ssn|card number)\b/.test(text)) flags.push('credential_shared');
if (/\b(refund|chargeback|dispute|invoice|charged)\b/.test(text)) { flags.push('billing_dispute'); labels.push('billing'); }
if (/\b(lawyer|legal|sue|lawsuit|compliance)\b/.test(text)) flags.push('legal');
if (/\b(security|breach|hacked|vulnerability|data leak)\b/.test(text)) flags.push('security');
if (/\b(delete my data|gdpr|privacy request|erase my data)\b/.test(text)) flags.push('data_deletion');
return [{ json: { ...$json, guardrailRiskFlags: flags, guardrailLabels: labels } }];

const knowledgePack = [
  { id: 'reset-password', title: 'Reset password', body: 'Open login page -> Forgot password -> enter email -> follow link. Link expires in 24h. If no email, check spam and allowlist our domain.' },
  { id: 'billing-portal', title: 'Billing and invoices', body: 'Go to Settings -> Billing to update card, download invoices, or cancel plan. Refunds and disputes need a human agent.' },
  { id: 'status', title: 'Outage or slowness', body: 'Check status.example.com. If no incident posted, tell us your region and timestamp; we will investigate.' }
];
const knowledgeContext = JSON.stringify(knowledgePack, null, 2);
return [{ json: { ...$json, knowledgePack, knowledgeContext } }];

const toolContext = {
  crm: 'TODO: replace no-op with CRM HTTP Request node when credentials exist.',
  order: 'TODO: replace no-op with order/status HTTP Request node when credentials exist.',
  status: 'TODO: replace no-op with status-page HTTP Request node when credentials exist.'
};
return [{ json: { ...$json, toolContext } }];

const upstream = $('Build AI Agent Input').first().json;
const res = $input.first().json;
const text = res.output || res.text || res.response || res.content || res.json || '';
let agent = null;
let parseFailed = false;
if (typeof text === 'object' && text !== null) agent = text;
else {
  try { agent = JSON.parse(String(text).trim().replace(/^```json\s*|\s*```$/g, '')); }
  catch (e) { parseFailed = true; }
}
if (parseFailed) agent = { answer: null, confidence: 0, needs_human: true, risk_flags: ['tool_failed'], labels: ['bot_escalated'], private_summary: 'AI Agent returned non-JSON output' };
return [{ json: { ...upstream, agentOutput: agent, agentParseFailed: parseFailed } }];

const upstream = $('Parse AI Agent Output').first().json;
let agent = upstream.agentOutput || {};
const risk = new Set(Array.isArray(agent.risk_flags) ? agent.risk_flags : []);
for (const flag of upstream.guardrailRiskFlags || []) risk.add(flag);
if (upstream.contextFailed) risk.add('tool_failed');
agent = { ...agent, risk_flags: Array.from(risk), labels: Array.from(new Set([...(Array.isArray(agent.labels) ? agent.labels : []), ...(upstream.guardrailLabels || [])])) };

const escalationFlags = ['refund','billing_dispute','legal','security','data_deletion','angry_customer','human_requested','credential_shared','tool_failed','unknown'];
const confidence = typeof agent.confidence === 'number' ? agent.confidence : 0;
const answer = typeof agent.answer === 'string' ? agent.answer.trim() : '';
const risky = agent.risk_flags.some((f) => escalationFlags.includes(f));
const shouldEscalate = agent.needs_human === true || confidence < 0.7 || risky || !answer || answer.length > 1200;
const action = shouldEscalate ? 'escalate' : 'reply';
const summary = typeof agent.private_summary === 'string' && agent.private_summary.trim() ? agent.private_summary.trim() : 'No summary provided by AI Agent.';
return [{ json: { ...upstream, action, intent: agent.intent || 'unknown', confidence, riskFlags: agent.risk_flags, knowledgeUsed: Array.isArray(agent.knowledge_used) ? agent.knowledge_used : [], publicAnswer: answer, privateSummary: [summary, `action=${action}`, `intent=${agent.intent || 'unknown'}`, `confidence=${confidence}`, `risk_flags=${agent.risk_flags.join(',')}`, `knowledge_used=${(Array.isArray(agent.knowledge_used) ? agent.knowledge_used : []).join(',')}`].join(' | '), labelSuggestions: agent.labels } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.failedTurns) staticData.failedTurns = {};
const item = $input.first().json;
const key = String(item.conversationId);
const failed = item.action === 'escalate' || Number(item.confidence || 0) < 0.75;
const count = failed ? Number(staticData.failedTurns[key] || 0) + 1 : 0;
staticData.failedTurns[key] = count;
const forceEscalate = count >= Number($env.FAILED_TURN_THRESHOLD || 2);
if (forceEscalate && item.action !== 'escalate') {
  return [{ json: { ...item, action: 'escalate', privateSummary: `${item.privateSummary} | forced_escalation_after_failed_turns=${count}`, labelSuggestions: Array.from(new Set([...(item.labelSuggestions || []), 'repeated_bot_failure'])) } }];
}
return [{ json: { ...item, failedTurnCount: count } }];
